package main

import (
	"log"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

const gossipInterval = 100 * time.Millisecond

type server struct {
	node *maelstrom.Node

	mu     sync.Mutex
	rumors map[int]struct{}
	peers  []string
	begun  bool
}

func main() {
	n := maelstrom.NewNode()
	s := &server{node: n, rumors: make(map[int]struct{})}

	n.Handle("init", s.handleInit)
	n.Handle("tell", s.handleTell)
	n.Handle("recall", s.handleRecall)
	n.Handle("neighbors", s.handleNeighbors)
	n.Handle("gossip", s.handleGossip)

	if err := n.Run(); err != nil {
		log.Fatal(err)
	}
}

// handleInit records the cluster membership and starts the anti-entropy loop.
// The library itself replies with init_ok after this handler returns.
func (s *server) handleInit(msg maelstrom.Message) error {
	s.mu.Lock()
	self := s.node.ID()
	s.peers = s.peers[:0]
	for _, id := range s.node.NodeIDs() {
		if id != self {
			s.peers = append(s.peers, id)
		}
	}
	start := !s.begun
	s.begun = true
	s.mu.Unlock()

	if start {
		go s.gossipLoop()
	}
	return nil
}

type tellBody struct {
	Type  string `json:"type"`
	Rumor int    `json:"rumor"`
}

func (s *server) handleTell(msg maelstrom.Message) error {
	var body tellBody
	if err := jsonUnmarshal(msg, &body); err != nil {
		return err
	}

	s.mu.Lock()
	_, known := s.rumors[body.Rumor]
	s.rumors[body.Rumor] = struct{}{}
	s.mu.Unlock()

	if err := s.node.Reply(msg, map[string]any{"type": "told"}); err != nil {
		return err
	}

	// Spread the news right away; periodic gossip covers anything lost.
	if !known {
		go s.broadcast()
	}
	return nil
}

type recallBody struct {
	Type   string `json:"type"`
	Rumors []int  `json:"rumors"`
}

func (s *server) handleRecall(msg maelstrom.Message) error {
	s.mu.Lock()
	rumors := make([]int, 0, len(s.rumors))
	for r := range s.rumors {
		rumors = append(rumors, r)
	}
	s.mu.Unlock()

	return s.node.Reply(msg, map[string]any{"type": "recalled", "rumors": rumors})
}

func (s *server) handleNeighbors(msg maelstrom.Message) error {
	// Membership from the init message is enough; the suggested topology is
	// only a hint. Still, acknowledge it as the protocol expects.
	return s.node.Reply(msg, map[string]any{"type": "neighbors_noted"})
}

type gossipBody struct {
	Type   string `json:"type"`
	Rumors []int  `json:"rumors"`
}

func (s *server) handleGossip(msg maelstrom.Message) error {
	var body gossipBody
	if err := jsonUnmarshal(msg, &body); err != nil {
		return err
	}

	extra := s.merge(body.Rumors)
	if len(extra) > 0 && msg.Src != "" {
		_ = s.node.Send(msg.Src, map[string]any{"type": "gossip", "rumors": extra})
	}
	return nil
}

// merge adds incoming rumors and returns the rumors we knew which the sender
// apparently did not.
func (s *server) merge(incoming []int) []int {
	seen := make(map[int]struct{}, len(incoming))

	s.mu.Lock()
	defer s.mu.Unlock()

	for _, r := range incoming {
		seen[r] = struct{}{}
		s.rumors[r] = struct{}{}
	}

	var extra []int
	for r := range s.rumors {
		if _, ok := seen[r]; !ok {
			extra = append(extra, r)
		}
	}
	return extra
}

func (s *server) snapshot() []int {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]int, 0, len(s.rumors))
	for r := range s.rumors {
		out = append(out, r)
	}
	return out
}

func (s *server) peerList() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]string, len(s.peers))
	copy(out, s.peers)
	return out
}

// broadcast pushes everything we know to every peer. Peers answer with
// anything they have that we did not include, so two messages fully reconcile
// a pair.
func (s *server) broadcast() {
	rumors := s.snapshot()
	if len(rumors) == 0 {
		return
	}
	for _, p := range s.peerList() {
		_ = s.node.Send(p, map[string]any{"type": "gossip", "rumors": rumors})
	}
}

func (s *server) gossipLoop() {
	ticker := time.NewTicker(gossipInterval)
	defer ticker.Stop()
	for range ticker.C {
		s.broadcast()
	}
}

